const ctx = $json;
const p = ctx.patient || {};
const clinic = ctx.clinic || {};
const isResched = ctx.intent === 'reschedule_request';
const reqType = isResched ? 'reschedule' : 'cancellation';
const ready = !!(p.name && (p.phone || p.email));
const day = $now.format('yyyy-LL-dd');
const leadKey = `${clinic.clinic_id}|${p.phone || p.email || 'nocontact'}|${reqType}|${day}`;

let reply;
if (ready) {
  reply = isResched
    ? `Thanks ${p.name}. We've received your request to reschedule your appointment (${p.existing_appt_datetime || 'existing time'}). This isn't confirmed yet — our team will contact you to arrange a new time.`
    : `Thanks ${p.name}. We've received your request to cancel your appointment (${p.existing_appt_datetime || 'existing time'}). This isn't a confirmed cancellation yet — our team will confirm shortly.`;
} else {
  reply = (ctx.next_question && ctx.next_question.trim()) ? ctx.next_question : `I can help with that. Could you share your full name, a phone or email, and the date/time of the existing appointment?`;
}

const row = {
  tab: 'Cancellations_Reschedules', operation: 'upsert', sheet_id: clinic.sheet_id, lead_key: leadKey,
  created_at: ctx.timestamp || $now.toISO(), session_id: ctx.session_id, patient_name: p.name || '',
  phone: p.phone || '', email: p.email || '', request_type: reqType,
  existing_appt_datetime: p.existing_appt_datetime || '', new_preferred_datetime: p.new_preferred_datetime || '',
  reason: p.reason || '', status: ready ? 'New' : 'Collecting', staff_notified: ready, sms_sent: false,
  notes: (clinic.test_mode ? '[TEST] ' : '') + (ctx.summary || '')
};

const emailBody = `Request type: ${reqType}\nUrgency: ${ctx.urgency}\nPatient: ${p.name}\nPhone: ${p.phone || '-'}\nEmail: ${p.email || '-'}\nExisting appt: ${p.existing_appt_datetime || '-'}\nNew preferred: ${p.new_preferred_datetime || '-'}\nReason: ${p.reason || '-'}\n\nSummary: ${ctx.summary}\nOriginal message: "${ctx.user_message}"\n\nRecommended next action: Locate the appointment and contact the patient. (Not yet actioned.)`;
const email = { to: clinic.staff_email, subject: `[${clinic.clinic_name}] ${reqType} request — ${p.name}`, body: (clinic.test_mode ? '[TEST MODE]\n' : '') + emailBody, reply_to: p.email || '' };

const smsBody = isResched
  ? `Hi ${p.name}, we received your reschedule request for ${clinic.clinic_name}. Our team will contact you to arrange a new time.`
  : `Hi ${p.name}, we received your cancellation request for ${clinic.clinic_name}. Our team will confirm shortly. This is not yet a confirmed cancellation.`;
const sms = { to: p.phone, body: smsBody, message_type: `${reqType}_received`, from: clinic.twilio_from, enabled: clinic.sms_enabled_patient, session_id: ctx.session_id, sheet_id: clinic.sheet_id };

return { json: { ...ctx, bot_response: reply, _ready: ready, _row: row, _email: email, _sms: sms } };
